//! PySCF parity gates for sci-form's correlated-excitation, ESP and IR
//! machinery (fichas F77, F78, F79b).
//!
//! These tests consume the fixtures generated by the oracles in
//! `scripts/validation/oracle_pyscf_*.py` (PySCF reference values) and
//! recompute the sci-form side, so CI validates real cross-library agreement
//! without installing PySCF.
//!
//! | ficha | what is compared                                        |
//! |-------|---------------------------------------------------------|
//! | F77   | sTDA UV-Vis energies/oscillator strengths vs PySCF TD-SCF |
//! | F78   | ESP grid vs PySCF density-based ESP (far field)          |
//! | F79b  | IR intensities (km/mol) vs PySCF dipole derivatives      |
//!
//! Regenerate the fixtures with:
//! ```bash
//! python scripts/validation/oracle_pyscf_stda.py
//! python scripts/validation/oracle_pyscf_esp.py
//! python scripts/validation/oracle_pyscf_ir.py
//! ```

use std::path::PathBuf;

use serde::Deserialize;

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("validation")
        .join(name)
}

fn load<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let path = fixture_path(name);
    let data = std::fs::read_to_string(&path).unwrap_or_else(|err| {
        panic!(
            "missing fixture {} ({err}); run `scripts/run_validation.sh` (or the matching oracle)",
            path.display()
        )
    });
    serde_json::from_str(&data).expect("invalid fixture JSON")
}

/// Write the measured metric to `target/validation/{ficha}.json` so
/// `scripts/validation/collect.py` can merge it into the human-readable
/// `reports/validation/summary.json` after the test run.
fn record(
    ficha: &str,
    observable: &str,
    metric: &str,
    value: f64,
    tolerance: f64,
    passed: bool,
    n_cases: usize,
) {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("validation");
    let _ = std::fs::create_dir(&dir);
    let payload = serde_json::json!({
        "ficha": ficha,
        "observable": observable,
        "metric": metric,
        "value": value,
        "tolerance": tolerance,
        "pass": passed,
        "n_cases": n_cases,
        "source": "tests/pyscf_parity.rs",
    });
    let path = dir.join(format!("{ficha}.json"));
    let mut rows: Vec<serde_json::Value> = std::fs::read_to_string(&path)
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
        .map(|value| match value {
            serde_json::Value::Array(items) => items,
            other => vec![other],
        })
        .unwrap_or_default();
    rows.retain(|row| row.get("observable").and_then(|v| v.as_str()) != Some(observable));
    rows.push(payload);
    let _ = std::fs::write(&path, serde_json::Value::Array(rows).to_string());
}

/// Bohr per Ångström (CODATA value, same as the rest of the test-suite).
const BOHR_PER_ANGSTROM: f64 = 1.0 / 0.529177210903;

/// Largest absolute difference between two (optionally truncated) vectors.
fn max_abs_diff(a: &[f64], b: &[f64]) -> f64 {
    let n = a.len().min(b.len());
    let mut worst = 0.0f64;
    for i in 0..n {
        worst = worst.max((a[i] - b[i]).abs());
    }
    worst
}

// ═══════════════════════════════════════════════════════════════════════════
// F79b — IR intensities vs PySCF dipole derivatives
// ═══════════════════════════════════════════════════════════════════════════

mod f79b_ir {
    use super::*;
    use sci_form::scf::scf_loop::ScfConfig;
    use sci_form::scf::types::MolecularSystem;
    use sci_form::spectroscopy::hessian::compute_hessian;
    use sci_form::spectroscopy::ir_intensities::{compute_ir_intensities, IrConfig};

    /// F79b compares the IR intensities of sci-form's SCF-based path
    /// (`spectroscopy::ir_intensities`) against a reference built from
    /// PySCF's analytic Hessian and its SCF dipoles.
    ///
    /// The gate found two unit bugs in the sci-form path, both of which were
    /// fixed (2026-10-21) before this gate was added:
    ///
    /// * `spectroscopy::hessian::compute_hessian` divided the frequency
    ///   conversion by an extra 2π (the Hartree-in-cm⁻¹ constant already
    ///   refers to the ordinary frequency ν = ω/2π), so every frequency was
    ///   6.283× too small.  The frequencies now agree with PySCF to
    ///   0.45 cm⁻¹ (H2O).
    /// * `spectroscopy::ir_intensities::compute_ir_intensities` applied the
    ///   Gaussian constant 42.2561 to a dipole derivative expressed in
    ///   e·a₀ per Bohr; the standard unit is Debye/(Å·√amu), so the
    ///   constant has to be multiplied by (2.541746/0.529177)² = 23.0706.
    ///   The intensities were 23.07× too small before the fix.

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        frequencies_cm1: Vec<f64>,
        intensity_exact_km_mol: Vec<f64>,
        intensity_mulliken_km_mol: Vec<f64>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Tolerances (measured 2026-10-21).
    ///
    /// * `FREQ_TOL` — sci-form's semi-numerical Hessian against PySCF's
    ///   analytic one.
    /// * `MULLIKEN_TOL` — sci-form's intensities against the reference
    ///   computed with the *same* Mulliken dipole model (this isolates the
    ///   Hessian difference).
    /// * `EXACT_TOL` — sci-form's intensities against the reference computed
    ///   with the exact density dipole; the residual is the Mulliken
    ///   approximation of the dipole derivative.
    const FREQ_TOL: f64 = 5.0;
    const MULLIKEN_TOL: f64 = 5.0;
    const EXACT_TOL: f64 = 60.0;

    /// Group the reference modes into (near-)degenerate groups: the
    /// semi-numerical Hessian of sci-form does not preserve the symmetry,
    /// so the individual members of a degenerate multiplet can be rotated
    /// into each other; the multiplet sum is invariant.
    fn degenerate_groups(freqs: &[f64]) -> Vec<Vec<usize>> {
        let mut groups: Vec<Vec<usize>> = Vec::new();
        for (i, &f) in freqs.iter().enumerate() {
            match groups.iter_mut().find(|g| (freqs[g[0]] - f).abs() < 1.0) {
                Some(g) => g.push(i),
                None => groups.push(vec![i]),
            }
        }
        groups
    }

    #[test]
    fn f79b_ir_intensities_match_pyscf() {
        let fixture: Fixture = load("pyscf_ir.json");
        assert!(!fixture.cases.is_empty());

        let mut worst_freq = (0.0f64, String::new());
        let mut worst_mulliken = (0.0f64, String::new());
        let mut worst_exact = (0.0f64, String::new());

        for case in &fixture.cases {
            let positions: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();
            let system = MolecularSystem::from_angstrom(&case.elements, &positions, 0, 1);

            let hessian = compute_hessian(&system, &ScfConfig::default(), 1e-3, 1e-3);
            let ir_config = IrConfig {
                // the fixed frequency conversion puts the OH stretches above
                // 4000 cm⁻¹, so the default window has to be widened
                freq_max: 6000.0,
                ..IrConfig::default()
            };
            let ir = compute_ir_intensities(&system, &hessian, &ir_config);

            assert_eq!(
                ir.frequencies.len(),
                case.frequencies_cm1.len(),
                "{}: mode count {} != {}",
                case.name,
                ir.frequencies.len(),
                case.frequencies_cm1.len()
            );

            for (i, &f) in case.frequencies_cm1.iter().enumerate() {
                let d = (ir.frequencies[i] - f).abs();
                if d > worst_freq.0 {
                    worst_freq = (d, format!("{} mode {i}", case.name));
                }
            }

            let groups = degenerate_groups(&case.frequencies_cm1);
            for group in &groups {
                let sum_ours: f64 = group.iter().map(|&i| ir.intensities[i]).sum();
                let sum_mull: f64 = group
                    .iter()
                    .map(|&i| case.intensity_mulliken_km_mol[i])
                    .sum();
                let sum_exact: f64 = group.iter().map(|&i| case.intensity_exact_km_mol[i]).sum();
                let d_mull = (sum_ours - sum_mull).abs();
                let d_exact = (sum_ours - sum_exact).abs();
                if d_mull > worst_mulliken.0 {
                    worst_mulliken = (d_mull, format!("{} group {group:?}", case.name));
                }
                if d_exact > worst_exact.0 {
                    worst_exact = (d_exact, format!("{} group {group:?}", case.name));
                }
            }
        }

        println!(
            "F79b IR vs PySCF: max|dnu| = {:.3} cm-1 ({}); max|dI| vs the Mulliken-dipole \
             reference = {:.3} km/mol ({}); max|dI| vs the exact-dipole reference = {:.3} km/mol ({})",
            worst_freq.0, worst_freq.1,
            worst_mulliken.0, worst_mulliken.1,
            worst_exact.0, worst_exact.1
        );

        assert!(
            worst_freq.0 <= FREQ_TOL,
            "IR frequencies deviate from PySCF by {:.3} cm-1 for {}",
            worst_freq.0,
            worst_freq.1
        );
        assert!(
            worst_mulliken.0 <= MULLIKEN_TOL,
            "IR intensities deviate from the Mulliken-dipole reference by {:.3} km/mol for {}",
            worst_mulliken.0,
            worst_mulliken.1
        );
        assert!(
            worst_exact.0 <= EXACT_TOL,
            "IR intensities deviate from the exact-dipole reference by {:.3} km/mol for {} \
             (the Mulliken dipole model)",
            worst_exact.0,
            worst_exact.1
        );

        record(
            "F79b",
            "ir_frequencies_max_abs_cm1",
            "max_abs",
            worst_freq.0,
            FREQ_TOL,
            worst_freq.0 <= FREQ_TOL,
            fixture.cases.len(),
        );
        record(
            "F79b",
            "ir_intensity_vs_mulliken_reference_max_abs",
            "max_abs",
            worst_mulliken.0,
            MULLIKEN_TOL,
            worst_mulliken.0 <= MULLIKEN_TOL,
            fixture.cases.len(),
        );
        record(
            "F79b",
            "ir_intensity_vs_exact_dipole_reference_max_abs",
            "max_abs",
            worst_exact.0,
            EXACT_TOL,
            worst_exact.0 <= EXACT_TOL,
            fixture.cases.len(),
        );
    }
}

mod f78_esp {
    use super::*;
    use sci_form::esp::compute_esp_grid;
    use sci_form::scf::scf_loop::{run_scf, ScfConfig};
    use sci_form::scf::types::MolecularSystem;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        charge: i32,
        #[allow(dead_code)]
        multiplicity: u32,
        mulliken_charges: Vec<f64>,
        total_charge: f64,
        origin: [f64; 3],
        spacing: f64,
        dims: [usize; 3],
        min_distance_ang: f64,
        esp_density: Vec<Option<f64>>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Distance (Ångström) beyond which the point-charge and the
    /// density-based potential are compared.
    const FAR_FIELD_ANG: f64 = 4.0;
    /// Measured 2026-10-21: 4.39e-3 (H2O) and 3.43e-3 (OH-) Hartree/e.
    const FAR_FIELD_TOL: f64 = 6e-3;
    /// Measured 2026-10-21: 3.2 % for the charged system (OH-).  The neutral
    /// H2O has no monopole: its far field is dominated by the dipole, and
    /// the Mulliken dipole is only ~55 % of the exact one, so the relative
    /// deviation stays at ~40 % and is *not* gated.
    const FAR_FIELD_REL_TOL: f64 = 0.05;
    /// Only points with |V| above this floor enter the relative measure
    /// (the nodal surface of the dipole makes the ratio meaningless).
    const REL_FLOOR: f64 = 0.02;
    /// Points closer than this to a nucleus are excluded from the
    /// intermediate-field metric (the 1/r nuclear singularity).
    const NEAR_FLOOR_ANG: f64 = 1.0;
    /// The grid must reproduce the analytic point-charge formula exactly.
    const GRID_FORMULA_TOL: f64 = 1e-12;

    /// sci-form's ESP value at one grid point (Mulliken point charges with
    /// the `min_distance` clamp), Hartree/e.
    fn point_charge_value(
        charges: &[f64],
        positions: &[[f64; 3]],
        point: [f64; 3],
        min_distance_ang: f64,
    ) -> f64 {
        let mut phi = 0.0f64;
        for (q, p) in charges.iter().zip(positions.iter()) {
            let dx = point[0] - p[0];
            let dy = point[1] - p[1];
            let dz = point[2] - p[2];
            let dist = (dx * dx + dy * dy + dz * dz).sqrt();
            let clamped = dist.max(min_distance_ang);
            phi += q / (clamped / 0.529177);
        }
        phi
    }

    #[test]
    fn f78_esp_grid_matches_pyscf_density_esp_in_far_field() {
        let fixture: Fixture = load("pyscf_esp.json");
        assert!(!fixture.cases.is_empty());

        let mut worst_far = (0.0f64, String::new());
        let mut worst_far_rel = (0.0f64, String::new());
        let mut worst_near = (0.0f64, String::new());
        let mut worst_formula = (0.0f64, String::new());
        let mut worst_monopole = (0.0f64, String::new());
        let mut n_clamped = 0usize;

        for case in &fixture.cases {
            let positions: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();

            let system = MolecularSystem::from_angstrom(&case.elements, &positions, case.charge, 1);
            let scf = run_scf(&system, &ScfConfig::default());
            assert!(scf.converged, "{}: SCF did not converge", case.name);
            assert_eq!(
                scf.mulliken_charges.len(),
                case.mulliken_charges.len(),
                "{}: charge count",
                case.name
            );

            let grid = compute_esp_grid(
                &case.elements,
                &positions,
                &scf.mulliken_charges,
                case.spacing,
                6.0,
            );
            assert_eq!(grid.dims, case.dims, "{}: grid dimensions", case.name);
            for k in 0..3 {
                assert!(
                    (grid.origin[k] - case.origin[k]).abs() < 1e-9,
                    "{}: grid origin {} != {}",
                    case.name,
                    grid.origin[k],
                    case.origin[k]
                );
            }
            assert_eq!(grid.values.len(), case.esp_density.len());

            let centroid = [
                positions.iter().map(|p| p[0]).sum::<f64>() / positions.len() as f64,
                positions.iter().map(|p| p[1]).sum::<f64>() / positions.len() as f64,
                positions.iter().map(|p| p[2]).sum::<f64>() / positions.len() as f64,
            ];

            let [nx, ny, nz] = case.dims;
            for ix in 0..nx {
                for iy in 0..ny {
                    for iz in 0..nz {
                        let idx = ix * ny * nz + iy * nz + iz;
                        let point = [
                            case.origin[0] + ix as f64 * case.spacing,
                            case.origin[1] + iy as f64 * case.spacing,
                            case.origin[2] + iz as f64 * case.spacing,
                        ];

                        // --- implementation check: the grid value must be the
                        // analytic point-charge expression with the clamp ---
                        let analytic = point_charge_value(
                            &scf.mulliken_charges,
                            &positions,
                            point,
                            case.min_distance_ang,
                        );
                        let formula_err = (grid.values[idx] - analytic).abs();
                        if formula_err > worst_formula.0 {
                            worst_formula = (formula_err, case.name.clone());
                        }

                        // --- clamp semantics ---
                        let mut d_min = f64::MAX;
                        for p in &positions {
                            let dx = point[0] - p[0];
                            let dy = point[1] - p[1];
                            let dz = point[2] - p[2];
                            d_min = d_min.min((dx * dx + dy * dy + dz * dz).sqrt());
                        }
                        if d_min < case.min_distance_ang {
                            n_clamped += 1;
                        }

                        let Some(density) = case.esp_density[idx] else {
                            continue; // exactly on a nucleus: 1/r singularity
                        };
                        let dev = (grid.values[idx] - density).abs();
                        if d_min > FAR_FIELD_ANG {
                            if dev > worst_far.0 {
                                worst_far = (dev, case.name.clone());
                            }
                            // relative measure only where the potential is
                            // significant and only for a charged system
                            if case.total_charge.abs() > 0.01 && density.abs() > REL_FLOOR {
                                let rel = dev / density.abs();
                                if rel > worst_far_rel.0 {
                                    worst_far_rel = (rel, case.name.clone());
                                }
                            }
                            // monopole convergence for a charged system:
                            // both models must approach Q / r around the
                            // centre of the nuclear charge distribution
                            if case.total_charge.abs() > 0.01 {
                                let dx = point[0] - centroid[0];
                                let dy = point[1] - centroid[1];
                                let dz = point[2] - centroid[2];
                                let r_bohr = (dx * dx + dy * dy + dz * dz).sqrt() / 0.529177;
                                let monopole = case.total_charge / r_bohr;
                                let m_dev = (grid.values[idx] - monopole).abs();
                                if m_dev > worst_monopole.0 {
                                    worst_monopole = (m_dev, case.name.clone());
                                }
                            }
                        } else if d_min > NEAR_FLOOR_ANG && dev > worst_near.0 {
                            worst_near = (dev, case.name.clone());
                        }
                    }
                }
            }
        }

        println!(
            "F78 ESP vs PySCF density ESP: far-field (> {FAR_FIELD_ANG} A) max|dV| = {:.3e} Ha/e ({}), \
             max relative = {:.3} ({}); near-field max|dV| = {:.3e} ({}); \
             grid formula max|Δ| = {:.3e} ({}); monopole residual {:.3e} ({}); {n_clamped} clamped points",
            worst_far.0, worst_far.1,
            worst_far_rel.0, worst_far_rel.1,
            worst_near.0, worst_near.1,
            worst_formula.0, worst_formula.1,
            worst_monopole.0, worst_monopole.1
        );

        assert!(
            worst_formula.0 <= GRID_FORMULA_TOL,
            "ESP grid values deviate from the analytic point-charge formula by {:.3e} Ha/e for {}",
            worst_formula.0,
            worst_formula.1
        );
        assert!(
            worst_far.0 <= FAR_FIELD_TOL,
            "far-field ESP deviates from the PySCF density ESP by {:.3e} Ha/e for {}",
            worst_far.0,
            worst_far.1
        );
        assert!(
            worst_far_rel.0 <= FAR_FIELD_REL_TOL,
            "far-field relative ESP deviation {:.3} for {}",
            worst_far_rel.0,
            worst_far_rel.1
        );

        record(
            "F78",
            "esp_far_field_max_abs_dev",
            "max_abs",
            worst_far.0,
            FAR_FIELD_TOL,
            worst_far.0 <= FAR_FIELD_TOL,
            fixture.cases.len(),
        );
        record(
            "F78",
            "esp_far_field_max_rel_dev",
            "max_abs",
            worst_far_rel.0,
            FAR_FIELD_REL_TOL,
            worst_far_rel.0 <= FAR_FIELD_REL_TOL,
            fixture.cases.len(),
        );
        record(
            "F78",
            "esp_near_field_max_abs_dev",
            "max_abs",
            worst_near.0,
            1.0,
            true,
            fixture.cases.len(),
        );
        record(
            "F78",
            "esp_grid_formula_max_abs",
            "max_abs",
            worst_formula.0,
            GRID_FORMULA_TOL,
            worst_formula.0 <= GRID_FORMULA_TOL,
            fixture.cases.len(),
        );
        record(
            "F78",
            "esp_monopole_residual_max_abs",
            "max_abs",
            worst_monopole.0,
            2e-2,
            worst_monopole.0 <= 2e-2,
            fixture.cases.len(),
        );
    }
}

mod f77_stda {
    use super::*;
    use sci_form::scf::extended_basis::{build_basis_set, BasisSetType};
    use sci_form::scf::scf_loop::{run_scf, ScfConfig};
    use sci_form::scf::two_electron::TwoElectronIntegrals;
    use sci_form::scf::types::MolecularSystem;
    use sci_form::spectroscopy::{compute_stda, compute_stda_with_exchange, ScfInput, StdaConfig};

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        n_basis: usize,
        n_electrons: usize,
        /// Active-space selection of sci-form's `StdaConfig` windows; kept
        /// for provenance (the reference port reproduces it exactly, which
        /// the implementation-parity gate verifies).
        #[allow(dead_code)]
        occ_active: Vec<usize>,
        #[allow(dead_code)]
        virt_active: Vec<usize>,
        mo_energy: Vec<f64>,
        tda_ev: Vec<f64>,
        tda_oscillator: Vec<f64>,
        tdhf_ev: Vec<f64>,
        tdhf_oscillator: Vec<f64>,
        tda_active_ev: Vec<f64>,
        tda_active_oscillator: Vec<f64>,
        tda_noex_active_ev: Vec<f64>,
        #[allow(dead_code)]
        tda_noex_active_oscillator: Vec<f64>,
        stda_ref_ev: Vec<f64>,
        stda_ref_oscillator: Vec<f64>,
        /// Reference port of the exchange-enabled sTDA
        /// (`compute_stda_with_exchange`, A_x = -2 ax (ij|ab)).
        stda_ex_ref_ev: Vec<f64>,
        stda_ex_ref_oscillator: Vec<f64>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        config: Config,
        cases: Vec<Case>,
    }

    #[derive(Deserialize)]
    struct Config {
        occ_window_ev: f64,
        virt_window_ev: f64,
        n_roots: usize,
    }

    /// Tolerances (measured 2026-10-21, see the module docs of the oracle).
    ///
    /// * `PARITY_EV` — sci-form's sTDA against the independent Python port of
    ///   the same algorithm: the implementation must agree to the accuracy
    ///   of the underlying SCF (the sci-form SCF reproduces PySCF's orbital
    ///   energies to ~1e-6 Ha).
    /// * `PARITY_OSC` — same for the oscillator strengths.
    /// * `CROSS_EV` / `CROSS_OSC` — sci-form's sTDA against PySCF's TDA on the
    ///   same active space.  sTDA is an approximation of TD-SCF: sci-form's
    ///   implementation replaces the two-electron Coulomb interaction by a
    ///   damped monopole model, so the deviations are expected to be large.
    ///   The bounds below are the measured maxima over the fixture set.
    /// * `CROSS_EV_EX` — the same comparison for the exchange-enabled sTDA
    ///   (`compute_stda_with_exchange`), which adds the Tamm-Dancoff exchange
    ///   term `-2 ax (ij|ab)` with `ax = 0.5`.
    const PARITY_EV: f64 = 1e-3;
    const PARITY_OSC: f64 = 1e-5;
    const CROSS_EV: f64 = 20.0;
    const CROSS_OSC: f64 = 5.0;
    const CROSS_EV_EX: f64 = 10.0;
    const CROSS_OSC_EX: f64 = 5.0;

    #[test]
    fn f77_stda_uvvis_matches_pyscf() {
        let fixture: Fixture = load("pyscf_stda.json");
        assert!(fixture.cases.len() >= 5);

        let config = StdaConfig {
            occ_window_ev: fixture.config.occ_window_ev,
            virt_window_ev: fixture.config.virt_window_ev,
            n_roots: fixture.config.n_roots,
            ..StdaConfig::default()
        };

        let mut worst_mo = (0.0f64, String::new());
        let mut worst_parity_ev = (0.0f64, String::new());
        let mut worst_parity_osc = (0.0f64, String::new());
        let mut worst_cross_ev = (0.0f64, String::new());
        let mut worst_cross_osc = (0.0f64, String::new());
        let mut worst_tda_full = (0.0f64, String::new());
        let mut worst_tda_full_osc = (0.0f64, String::new());
        let mut worst_tdhf_ev = (0.0f64, String::new());
        let mut worst_tdhf_osc = (0.0f64, String::new());
        let mut worst_exchange_gap = (0.0f64, String::new());
        let mut worst_monopole_gap = (0.0f64, String::new());
        let mut worst_ex_parity_ev = (0.0f64, String::new());
        let mut worst_ex_parity_osc = (0.0f64, String::new());
        let mut worst_ex_cross_ev = (0.0f64, String::new());
        let mut worst_ex_cross_osc = (0.0f64, String::new());
        let mut worst_ex_tda_full = (0.0f64, String::new());
        let mut worst_ex_tda_full_osc = (0.0f64, String::new());
        let mut worst_ex_tdhf_ev = (0.0f64, String::new());
        let mut worst_ex_tdhf_osc = (0.0f64, String::new());
        let mut worst_exchange_effect = (0.0f64, String::new());

        for case in &fixture.cases {
            let positions_ang: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();
            let positions_bohr: Vec<[f64; 3]> = positions_ang
                .iter()
                .map(|p| {
                    [
                        p[0] * BOHR_PER_ANGSTROM,
                        p[1] * BOHR_PER_ANGSTROM,
                        p[2] * BOHR_PER_ANGSTROM,
                    ]
                })
                .collect();

            let basis = build_basis_set(BasisSetType::Sto3g, &case.elements, &positions_bohr);
            assert_eq!(
                basis.n_basis, case.n_basis,
                "{}: n_basis {} != PySCF {}",
                case.name, basis.n_basis, case.n_basis
            );

            let system = MolecularSystem::from_angstrom(&case.elements, &positions_ang, 0, 1);
            let result = run_scf(&system, &ScfConfig::default());
            assert!(result.converged, "{}: SCF did not converge", case.name);
            assert_eq!(result.n_basis, case.n_basis);
            assert_eq!(result.n_electrons, case.n_electrons);

            // The SCF reference must be the same on both sides.
            let mut ours_mo = result.orbital_energies.clone();
            ours_mo.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let mo_err = max_abs_diff(&ours_mo, &case.mo_energy);
            if mo_err > worst_mo.0 {
                worst_mo = (mo_err, case.name.clone());
            }

            let scf_input = ScfInput::from(&result);
            let spectrum = compute_stda(
                &scf_input,
                &basis.function_to_atom,
                &positions_bohr,
                &config,
            );

            let ours_ev: Vec<f64> = spectrum.transitions.iter().map(|t| t.energy_ev).collect();
            let ours_osc: Vec<f64> = spectrum
                .transitions
                .iter()
                .map(|t| t.oscillator_strength)
                .collect();

            assert_eq!(
                ours_ev.len(),
                case.stda_ref_ev.len(),
                "{}: sTDA returned {} transitions, the reference port has {}",
                case.name,
                ours_ev.len(),
                case.stda_ref_ev.len()
            );

            // --- implementation parity against the independent port -------
            let parity_ev = max_abs_diff(&ours_ev, &case.stda_ref_ev);
            let parity_osc = max_abs_diff(&ours_osc, &case.stda_ref_oscillator);
            if parity_ev > worst_parity_ev.0 {
                worst_parity_ev = (parity_ev, case.name.clone());
            }
            if parity_osc > worst_parity_osc.0 {
                worst_parity_osc = (parity_osc, case.name.clone());
            }

            // --- cross-library comparison against PySCF's TDA --------------
            let cross_ev = max_abs_diff(&ours_ev, &case.tda_active_ev);
            let cross_osc = max_abs_diff(&ours_osc, &case.tda_active_oscillator);
            if cross_ev > worst_cross_ev.0 {
                worst_cross_ev = (cross_ev, case.name.clone());
            }
            if cross_osc > worst_cross_osc.0 {
                worst_cross_osc = (cross_osc, case.name.clone());
            }

            // --- deviation against the full TD-SCF references ---------------
            // (PySCF's full-space TDA and its TD-SCF/TDHF excitation energies)
            let tda_full_ev = max_abs_diff(&ours_ev, &case.tda_ev);
            let tda_full_osc = max_abs_diff(&ours_osc, &case.tda_oscillator);
            if tda_full_ev > worst_tda_full.0 {
                worst_tda_full = (tda_full_ev, case.name.clone());
            }
            if tda_full_osc > worst_tda_full_osc.0 {
                worst_tda_full_osc = (tda_full_osc, case.name.clone());
            }
            let tdhf_ev = max_abs_diff(&ours_ev, &case.tdhf_ev);
            let tdhf_osc = max_abs_diff(&ours_osc, &case.tdhf_oscillator);
            if tdhf_ev > worst_tdhf_ev.0 {
                worst_tdhf_ev = (tdhf_ev, case.name.clone());
            }
            if tdhf_osc > worst_tdhf_osc.0 {
                worst_tdhf_osc = (tdhf_osc, case.name.clone());
            }

            // --- error decomposition ---------------------------------------
            // exchange gap: how much the missing exchange term (StdaConfig::ax
            // is never used) moves the energies; monopole gap: how much the
            // monopole approximation of the Coulomb interaction moves them.
            let exchange_gap = max_abs_diff(&case.tda_noex_active_ev, &case.tda_active_ev);
            let monopole_gap = max_abs_diff(&case.stda_ref_ev, &case.tda_noex_active_ev);
            if exchange_gap > worst_exchange_gap.0 {
                worst_exchange_gap = (exchange_gap, case.name.clone());
            }
            if monopole_gap > worst_monopole_gap.0 {
                worst_monopole_gap = (monopole_gap, case.name.clone());
            }

            // --- exchange-enabled sTDA (A_x = -2 ax (ij|ab)) -----------------
            let eris = TwoElectronIntegrals::compute(&basis);
            let spectrum_ex = compute_stda_with_exchange(
                &scf_input,
                &basis.function_to_atom,
                &positions_bohr,
                &config,
                &eris,
            );
            let ours_ex_ev: Vec<f64> = spectrum_ex
                .transitions
                .iter()
                .map(|t| t.energy_ev)
                .collect();
            let ours_ex_osc: Vec<f64> = spectrum_ex
                .transitions
                .iter()
                .map(|t| t.oscillator_strength)
                .collect();

            assert_eq!(
                ours_ex_ev.len(),
                case.stda_ex_ref_ev.len(),
                "{}: exchange-enabled sTDA returned {} transitions, the reference port has {}",
                case.name,
                ours_ex_ev.len(),
                case.stda_ex_ref_ev.len()
            );

            let ex_parity_ev = max_abs_diff(&ours_ex_ev, &case.stda_ex_ref_ev);
            if ex_parity_ev > worst_ex_parity_ev.0 {
                worst_ex_parity_ev = (ex_parity_ev, case.name.clone());
            }
            let ex_parity_osc = max_abs_diff(&ours_ex_osc, &case.stda_ex_ref_oscillator);
            if ex_parity_osc > worst_ex_parity_osc.0 {
                worst_ex_parity_osc = (ex_parity_osc, case.name.clone());
            }

            let ex_cross_ev = max_abs_diff(&ours_ex_ev, &case.tda_active_ev);
            if ex_cross_ev > worst_ex_cross_ev.0 {
                worst_ex_cross_ev = (ex_cross_ev, case.name.clone());
            }
            let ex_cross_osc = max_abs_diff(&ours_ex_osc, &case.tda_active_oscillator);
            if ex_cross_osc > worst_ex_cross_osc.0 {
                worst_ex_cross_osc = (ex_cross_osc, case.name.clone());
            }

            let ex_tda_full = max_abs_diff(&ours_ex_ev, &case.tda_ev);
            if ex_tda_full > worst_ex_tda_full.0 {
                worst_ex_tda_full = (ex_tda_full, case.name.clone());
            }
            let ex_tda_full_osc = max_abs_diff(&ours_ex_osc, &case.tda_oscillator);
            if ex_tda_full_osc > worst_ex_tda_full_osc.0 {
                worst_ex_tda_full_osc = (ex_tda_full_osc, case.name.clone());
            }
            let ex_tdhf = max_abs_diff(&ours_ex_ev, &case.tdhf_ev);
            if ex_tdhf > worst_ex_tdhf_ev.0 {
                worst_ex_tdhf_ev = (ex_tdhf, case.name.clone());
            }
            let ex_tdhf_osc = max_abs_diff(&ours_ex_osc, &case.tdhf_oscillator);
            if ex_tdhf_osc > worst_ex_tdhf_osc.0 {
                worst_ex_tdhf_osc = (ex_tdhf_osc, case.name.clone());
            }

            // how much the exchange term moves the energies
            let exchange_effect = max_abs_diff(&ours_ev, &ours_ex_ev);
            if exchange_effect > worst_exchange_effect.0 {
                worst_exchange_effect = (exchange_effect, case.name.clone());
            }
        }

        println!(
            "F77 sTDA vs PySCF: parity vs port max|dE| = {:.3e} eV ({}), max|df| = {:.3e} ({}); \
             cross-library vs TDA(max|dE| = {:.3} eV, {}), max|df| = {:.3} ({}); \
             vs full-space TDA max|dE| = {:.3} eV ({}), max|df| = {:.3} ({}); \
             vs TDHF max|dE| = {:.3} eV ({}), max|df| = {:.3} ({}); \
             exchange gap {:.3} eV ({}), monopole gap {:.3} eV ({})",
            worst_parity_ev.0,
            worst_parity_ev.1,
            worst_parity_osc.0,
            worst_parity_osc.1,
            worst_cross_ev.0,
            worst_cross_ev.1,
            worst_cross_osc.0,
            worst_cross_osc.1,
            worst_tda_full.0,
            worst_tda_full.1,
            worst_tda_full_osc.0,
            worst_tda_full_osc.1,
            worst_tdhf_ev.0,
            worst_tdhf_ev.1,
            worst_tdhf_osc.0,
            worst_tdhf_osc.1,
            worst_exchange_gap.0,
            worst_exchange_gap.1,
            worst_monopole_gap.0,
            worst_monopole_gap.1
        );

        println!(
            "F77 sTDA *with exchange* vs PySCF: parity vs port max|dE| = {:.3e} eV ({}), \
             max|df| = {:.3e} ({}); cross-library vs TDA(max|dE| = {:.3} eV, {}), \
             max|df| = {:.3} ({}); vs full-space TDA max|dE| = {:.3} eV ({}); \
             vs TDHF max|dE| = {:.3} eV ({}); the exchange term moves the energies by up to \
             {:.3} eV ({})",
            worst_ex_parity_ev.0,
            worst_ex_parity_ev.1,
            worst_ex_parity_osc.0,
            worst_ex_parity_osc.1,
            worst_ex_cross_ev.0,
            worst_ex_cross_ev.1,
            worst_ex_cross_osc.0,
            worst_ex_cross_osc.1,
            worst_ex_tda_full.0,
            worst_ex_tda_full.1,
            worst_ex_tdhf_ev.0,
            worst_ex_tdhf_ev.1,
            worst_exchange_effect.0,
            worst_exchange_effect.1
        );

        assert!(
            worst_mo.0 <= 1e-6,
            "SCF orbital energies deviate from PySCF by {:.3e} Ha for {}",
            worst_mo.0,
            worst_mo.1
        );
        assert!(
            worst_parity_ev.0 <= PARITY_EV,
            "sTDA implementation deviates from the reference port by {:.3e} eV for {}",
            worst_parity_ev.0,
            worst_parity_ev.1
        );
        assert!(
            worst_parity_osc.0 <= PARITY_OSC,
            "sTDA oscillator strengths deviate from the reference port by {:.3e} for {}",
            worst_parity_osc.0,
            worst_parity_osc.1
        );
        assert!(
            worst_cross_ev.0 <= CROSS_EV,
            "sTDA energies deviate from PySCF's TDA by {:.3} eV for {} \
             (sTDA uses a monopole Coulomb model and has no exchange term)",
            worst_cross_ev.0,
            worst_cross_ev.1
        );
        assert!(
            worst_cross_osc.0 <= CROSS_OSC,
            "sTDA oscillator strengths deviate from PySCF's TDA by {:.3} for {}",
            worst_cross_osc.0,
            worst_cross_osc.1
        );
        assert!(
            worst_ex_parity_ev.0 <= PARITY_EV,
            "the exchange-enabled sTDA deviates from the reference port by {:.3e} eV for {}",
            worst_ex_parity_ev.0,
            worst_ex_parity_ev.1
        );
        assert!(
            worst_ex_parity_osc.0 <= PARITY_OSC,
            "the exchange-enabled sTDA oscillator strengths deviate from the reference port \
             by {:.3e} for {}",
            worst_ex_parity_osc.0,
            worst_ex_parity_osc.1
        );
        assert!(
            worst_ex_cross_ev.0 <= CROSS_EV_EX,
            "the exchange-enabled sTDA deviates from PySCF's TDA by {:.3} eV for {}",
            worst_ex_cross_ev.0,
            worst_ex_cross_ev.1
        );
        assert!(
            worst_ex_cross_osc.0 <= CROSS_OSC_EX,
            "the exchange-enabled sTDA oscillator strengths deviate from PySCF's TDA by \
             {:.3} for {}",
            worst_ex_cross_osc.0,
            worst_ex_cross_osc.1
        );
        assert!(
            worst_ex_tda_full.0 <= CROSS_EV_EX,
            "the exchange-enabled sTDA deviates from PySCF's full-space TDA by {:.3} eV for {}",
            worst_ex_tda_full.0,
            worst_ex_tda_full.1
        );
        assert!(
            worst_ex_tdhf_ev.0 <= CROSS_EV_EX,
            "the exchange-enabled sTDA deviates from PySCF's TDHF by {:.3} eV for {}",
            worst_ex_tdhf_ev.0,
            worst_ex_tdhf_ev.1
        );

        record(
            "F77",
            "stda_scf_orbital_energy_max_abs",
            "max_abs",
            worst_mo.0,
            1e-6,
            worst_mo.0 <= 1e-6,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_impl_parity_max_abs_ev",
            "max_abs",
            worst_parity_ev.0,
            PARITY_EV,
            worst_parity_ev.0 <= PARITY_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_impl_parity_max_abs_oscillator",
            "max_abs",
            worst_parity_osc.0,
            PARITY_OSC,
            worst_parity_osc.0 <= PARITY_OSC,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tda_max_abs_ev",
            "max_abs",
            worst_cross_ev.0,
            CROSS_EV,
            worst_cross_ev.0 <= CROSS_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tda_max_abs_oscillator",
            "max_abs",
            worst_cross_osc.0,
            CROSS_OSC,
            worst_cross_osc.0 <= CROSS_OSC,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tda_fullspace_max_abs_ev",
            "max_abs",
            worst_tda_full.0,
            CROSS_EV,
            worst_tda_full.0 <= CROSS_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tda_fullspace_max_abs_oscillator",
            "max_abs",
            worst_tda_full_osc.0,
            CROSS_OSC,
            worst_tda_full_osc.0 <= CROSS_OSC,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tdhf_max_abs_ev",
            "max_abs",
            worst_tdhf_ev.0,
            CROSS_EV,
            worst_tdhf_ev.0 <= CROSS_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_vs_pyscf_tdhf_max_abs_oscillator",
            "max_abs",
            worst_tdhf_osc.0,
            CROSS_OSC,
            worst_tdhf_osc.0 <= CROSS_OSC,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_missing_exchange_gap_max_abs_ev",
            "max_abs",
            worst_exchange_gap.0,
            CROSS_EV,
            worst_exchange_gap.0 <= CROSS_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_monopole_coulomb_gap_max_abs_ev",
            "max_abs",
            worst_monopole_gap.0,
            CROSS_EV,
            worst_monopole_gap.0 <= CROSS_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_impl_parity_max_abs_ev",
            "max_abs",
            worst_ex_parity_ev.0,
            PARITY_EV,
            worst_ex_parity_ev.0 <= PARITY_EV,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_impl_parity_max_abs_oscillator",
            "max_abs",
            worst_ex_parity_osc.0,
            PARITY_OSC,
            worst_ex_parity_osc.0 <= PARITY_OSC,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tda_max_abs_ev",
            "max_abs",
            worst_ex_cross_ev.0,
            CROSS_EV_EX,
            worst_ex_cross_ev.0 <= CROSS_EV_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tda_max_abs_oscillator",
            "max_abs",
            worst_ex_cross_osc.0,
            CROSS_OSC_EX,
            worst_ex_cross_osc.0 <= CROSS_OSC_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tda_fullspace_max_abs_ev",
            "max_abs",
            worst_ex_tda_full.0,
            CROSS_EV_EX,
            worst_ex_tda_full.0 <= CROSS_EV_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tda_fullspace_max_abs_oscillator",
            "max_abs",
            worst_ex_tda_full_osc.0,
            CROSS_OSC_EX,
            worst_ex_tda_full_osc.0 <= CROSS_OSC_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tdhf_max_abs_ev",
            "max_abs",
            worst_ex_tdhf_ev.0,
            CROSS_EV_EX,
            worst_ex_tdhf_ev.0 <= CROSS_EV_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_vs_pyscf_tdhf_max_abs_oscillator",
            "max_abs",
            worst_ex_tdhf_osc.0,
            CROSS_OSC_EX,
            worst_ex_tdhf_osc.0 <= CROSS_OSC_EX,
            fixture.cases.len(),
        );
        record(
            "F77",
            "stda_exchange_term_effect_max_abs_ev",
            "max_abs",
            worst_exchange_effect.0,
            CROSS_EV,
            worst_exchange_effect.0 <= CROSS_EV,
            fixture.cases.len(),
        );
    }
}
